  public static int lookup(String runs, int cp) { int lo = 0, hi = runs.length() / 3 - 1; while (lo < hi) { int m = (lo + hi + 1) >>> 1; if ((runs.charAt(3 * m) << 16 | runs.charAt(3 * m + 1)) <= cp) lo = m; else hi = m - 1; } return runs.charAt(3 * lo + 2); }
  /** the index in BLOCK_STARTS of the run containing cp */
  public static int blockRun(int cp) { int lo = 0, hi = BLOCK_STARTS.length - 1; while (lo < hi) { int m = (lo + hi + 1) >>> 1; if (BLOCK_STARTS[m] <= cp) lo = m; else hi = m - 1; } return lo; }
  private static int[] scriptStarts, scriptOf;
  /** the script ordinal of cp */
  public static int script(int cp) {
    if (scriptStarts == null) { int n = SCRIPTS.length() / 3; int[] s = new int[n], o = new int[n]; for (int i = 0; i < n; i++) { s[i] = SCRIPTS.charAt(3 * i) << 16 | SCRIPTS.charAt(3 * i + 1); o[i] = SCRIPTS.charAt(3 * i + 2); } scriptOf = o; scriptStarts = s; }
    int lo = 0, hi = scriptStarts.length - 1; while (lo < hi) { int m = (lo + hi + 1) >>> 1; if (scriptStarts[m] <= cp) lo = m; else hi = m - 1; } return scriptOf[lo];
  }
